import{_ as o,o as t,c as e,a5 as i}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 2 话 动画与过渡：流畅的时间维度","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.02-animation-transition.md","filePath":"comics/css/EP.02-animation-transition.md","lastUpdated":1793421609000}'),n={name:"comics/css/EP.02-animation-transition.md"};function r(s,a,l,c,d,h){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="漫画-·-第-2-话-动画与过渡-流畅的时间维度" tabindex="-1">漫画 · 第 2 话 动画与过渡：流畅的时间维度 <a class="header-anchor" href="#漫画-·-第-2-话-动画与过渡-流畅的时间维度" aria-label="Permalink to &quot;漫画 · 第 2 话 动画与过渡：流畅的时间维度&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/02-animation-transition">docs/css/02-animation-transition.md</a> ｜ 原画：<a href="./EP.02-animation-transition.svg">EP.02-animation-transition.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。给盒子加了&quot;飞入&quot;动画，结果帧率从 60 掉到 28，她决定查清&quot;流畅&quot;到底是谁说了算。</li><li><strong>码叔</strong>：划重点担当，结尾带走三句性能铁律。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p><code>transition: all</code> + 动 <code>left</code> 让像素酱的动画卡成了幻灯片。顺着渲染流水线四站（Style → Layout → Paint → Composite）往下查，她发现浏览器只给 <code>transform</code> 和 <code>opacity</code> 开了绿色快车道。最后 transition 与 animation 各归其位：一个管状态补间，一个管主动时间线。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>两个经典翻车点叠在一起：<strong>动 <code>left</code> 属于 Layout 属性，每帧都触发重排</strong>，动画循环时浏览器整帧整帧地重新布局；<code>transition: all</code> 则是隐式过渡，颜色、内边距等&quot;无辜属性&quot;也会被拉长，性能不可控。FPS 从 60 跌到 28，人眼立刻感知&quot;卡顿&quot;。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>渲染流水线四站：<strong>Style → Layout → Paint → Composite</strong>。属性按触发代价分三档：</p><ul><li>Layout 属性（width/left/top）：重排 + 重绘，代价最高；</li><li>Paint 属性（color/box-shadow）：不重排但要重绘像素；</li><li><strong>Composite 属性（transform/opacity）</strong>：元素被提升为独立合成层，动画只改层的矩阵，由合成器线程在 GPU 上完成——完全跳过前三站。</li></ul><p>这就是&quot;只动 transform 与 opacity&quot;铁律的由来。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>两者各司其职：<strong>transition 是&quot;被动响应的补间&quot;</strong>——必须由状态变化触发，适合按钮反馈（hover 上浮 2px + 回弹贝塞尔 <code>cubic-bezier(.34,1.56,.64,1)</code>，y &gt; 1 产生过冲手感）；<strong>animation 是&quot;主动执行的时间线&quot;</strong>——<code>@keyframes</code> 定义关键帧，可自动播放、无限循环，三点加载动画用同一 keyframes + 负 delay 错相，<code>alternate</code> 来回摆动。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>transition 管状态补间，animation 管可循环可编排的时间线。</li><li>只动 <code>transform</code> 和 <code>opacity</code>；显式列出过渡属性，<strong>禁用 <code>transition: all</code></strong>。</li><li><code>fill-mode: both</code> 防首尾闪帧；<code>will-change</code> 是手术刀不是维生素；永远给 <code>prefers-reduced-motion</code> 留退路。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么侧边栏折叠（240px ⇄ 64px）不能用 <code>transform: scaleX</code> 代替 <code>width</code> 过渡？</p><p><strong>答</strong>：侧栏参与文档流布局，<code>scaleX</code> 只是视觉压缩，右侧内容不会回流腾出空间，等于&quot;盖住&quot;而非&quot;收起&quot;。布局动画不可避免时，正确姿势是：受控地过渡 <code>width</code>、把波及面降到最小、文字用 <code>overflow: hidden</code> 防换行闪动。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>transition 全参数实验台 + 贝塞尔曲线可视化：<a href="./../../examples/css/02-animation-transition/index-01-transition-playground.html">examples/css/02-animation-transition/</a></li><li>@keyframes 八个子属性实验台：<a href="./../../examples/css/02-animation-transition/index-02-keyframes-animation.html">index-02-keyframes-animation.html</a></li><li>三种触发方式 + 性能对照 + reduced-motion：<a href="./../../examples/css/02-animation-transition/index-03-trigger-performance.html">index-03-trigger-performance.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>一排卡片怎么等高？按钮怎么贴底？长标题为什么把导航挤爆？第 3 话《Flexbox》，一根轴上的声明式布局。</p>',24)])])}const p=o(n,[["render",r]]);export{u as __pageData,p as default};
